{"candidate": {"label": "barred", "description": "This means being kept out of a place or activity by a ban, with the locked door or refusal standing between one and something one wants, day after day."},
 "traits": [
  {"id": 1, "label": "isolated", "description": "This means having no friends or contacts anywhere, nobody to call for a favor, a job lead or a word in the right ear."}
 ]}

{"candidate": {"label": "discarded", "description": "This means living with friends and colleagues who no longer call or include one, sitting alone through evenings once shared, and slowly learning to fill the empty hours without them."},
 "traits": [
  {"id": 1, "label": "Gesellschaft (from Tönnies)", "description": "This means living peaceably alongside others without being joined to them, out for oneself alone and in tension with everyone else, and giving nothing except in exchange for at least as much."}
 ]}

{"candidate": {"label": "attenuated", "description": "This means living with a body that has lost strength and reserve, moving slowly, needing help with stairs and heavy tasks, and conserving energy for the few things that matter most."},
 "traits": [
  {"id": 1, "label": "in chronic pain", "description": "This means hurting every day for years, from a bad back, worn joints or an old injury: painkillers that only take the edge off, a heating pad, and sleep broken by it."}
 ]}

{"candidate": {"label": "friendless", "description": "This means going through each day without close companions, eating alone and spending evenings in silence, and feeling quietly left out whenever others mention plans or gatherings."},
 "traits": [
  {"id": 1, "label": "Gesellschaft (from Tönnies)", "description": "This means living peaceably alongside others without being joined to them, out for oneself alone and in tension with everyone else, and giving nothing except in exchange for at least as much."}
 ]}

{"candidate": {"label": "forsaken", "description": "This means living with the aftermath of being left by those who promised to stay, keeping a wary distance from new people, and speaking of the desertion with bitterness."},
 "traits": [
  {"id": 1, "label": "languishing", "description": "This means doing poorly, being stuck in place, living for no purpose, muddling through the days, drifting from one's people, and feeling hollow without knowing why."}
 ]}

{"candidate": {"label": "cast-out", "description": "This means living apart from the family or group that has rejected one, going without its support and company, and carrying the hurt of exclusion into every new setting."},
 "traits": [
  {"id": 1, "label": "Gesellschaft (from Tönnies)", "description": "This means living peaceably alongside others without being joined to them, out for oneself alone and in tension with everyone else, and giving nothing except in exchange for at least as much."},
  {"id": 2, "label": "solitary", "description": "This means being solitary by choice: preferring one's own company, working, eating, and traveling alone, declining invitations without regret, and keeping other people at a distance rather than seeking them out."}
 ]}

{"candidate": {"label": "homesick", "description": "This means feeling a pull toward home at odd moments in unfamiliar places, writing or calling family often, and letting talk drift back to familiar streets and kitchens."},
 "traits": [
  {"id": 1, "label": "lonely", "description": "This means wanting company and having none: evenings with no one to call, weekends that stretch empty, chatting to the cashier for the contact, and missing people more than one lets on."}
 ]}

{"candidate": {"label": "blacklisted", "description": "This means being shut out of work by a list one cannot see or contest, finding offers vanish once an employer checks, and living with doors closed by reputation alone."},
 "traits": [
  {"id": 1, "label": "unpopular", "description": "This means not being liked by anyone in the class or the office, picked last, left off every invitation, and missed by nobody when away."},
  {"id": 2, "label": "unsupported", "description": "This means having nobody in one's corner: no one to drive one home from the hospital, to lend the rent, to listen after a bad day, and carrying every load alone."},
  {"id": 3, "label": "isolated", "description": "This means having no friends or contacts anywhere, nobody to call for a favor, a job lead or a word in the right ear."}
 ]}

{"candidate": {"label": "misused", "description": "This means being used by others who take your time, money or labor and give little back, living with resentment and wariness, and slowly losing faith in those around you."},
 "traits": [
  {"id": 1, "label": "burned-out", "description": "This means being drained by work that once mattered, going through the motions, cynical about the point of it all, and unable to summon the effort or the care it used to get."}
 ]}

{"candidate": {"label": "horny", "description": "This means being quick to desire, letting thoughts drift toward sex at odd moments, and pursuing partners more eagerly than the situation calls for."},
 "traits": [
  {"id": 1, "label": "impulsive", "description": "This means acting on immediate desires or urges without taking time to consider potential consequences, alternatives, or long-term implications."},
  {"id": 2, "label": "irrestrainable", "description": "This means acting on impulse with no brake on one's conduct, letting desire, anger, or whim carry one forward regardless of consequences, and treating self-control as something one never bothers to practice."}
 ]}

{"candidate": {"label": "unsuccessful", "description": "This means living for years without the advancement or recognition one hoped for, working at modestly paid jobs, and measuring each day against goals that never came."},
 "traits": [
  {"id": 1, "label": "defeatist", "description": "This means expecting a hard goal to fail, giving up at the first setback or rejection, and dropping it for good on the grounds that it was never going to work."},
  {"id": 2, "label": "unambitious", "description": "This means doing the job and going home, wanting no promotion and no bigger goal, and puzzled by anyone who is always reaching for more."}
 ]}

{"candidate": {"label": "weakening", "description": "This means watching strength drain from the body month by month: needing help with stairs and jars, sitting down sooner, and speaking of what one used to manage easily."},
 "traits": [
  {"id": 1, "label": "chronically-ill", "description": "This means living for years with an illness that is managed, not cured: daily medication, specialist appointments on the calendar, flares that take out a week, and energy rationed day by day."},
  {"id": 2, "label": "in chronic pain", "description": "This means hurting every day for years, from a bad back, worn joints or an old injury: painkillers that only take the edge off, a heating pad, and sleep broken by it."}
 ]}
